     4	package encounter
     5	
     6	import (
     7		"fmt"
     8		"slices"
     9		"sort"
    10	
    11		"github.com/KirkDiggler/rpg-toolkit/play/clock"
    12		"github.com/KirkDiggler/rpg-toolkit/play/intel"
    13		"github.com/KirkDiggler/rpg-toolkit/play/record"
    14		"github.com/KirkDiggler/rpg-toolkit/tools/spatial"
    15	)
    16	
    17	// EncounterData is the persistent representation of an Encounter.
    18	// Outcome is omitted when the encounter is open; present when closed.
    19	// All leaves (Clock, Intel, Log) embed their Data types verbatim.
    20	// Deciders are NOT persisted; they are re-registered at load.
    21	type EncounterData struct {
    22		Outcome     *OutcomeData   `json:"outcome,omitempty"`
    23		Clock       clock.TickData `json:"clock"`
    24		Intel       intel.Data     `json:"intel"`
    25		Log         record.LogData `json:"log"`
    26		Field       FieldData      `json:"field"`
    27		Members     []MemberData   `json:"members"`
    28		Endings     []EndingData   `json:"endings"`
    29		EverMembers []MemberID     `json:"ever_members"`
    30	}
    31	
    32	// OutcomeData is the persistent representation of an Outcome.
    33	type OutcomeData struct {
    34		Ending  string              `json:"ending"`
    35		At      uint64              `json:"at,omitempty"`
    36		Members []MemberOutcomeData `json:"members,omitempty"`
    37	}
    38	
    39	// MemberOutcomeData is a member's position when the encounter closed.
    40	type MemberOutcomeData struct {
    41		ID       MemberID     `json:"id"`
    42		Room     string       `json:"room"`
    43		Position PositionData `json:"position"`
    44	}
    45	
    46	// FieldData is the persistent representation of the encounter's field.
    47	// Rooms hold the composition's own descriptions (mirroring RoomInput exactly).
    48	// Connections are the declared room links.
    49	type FieldData struct {
    50		Rooms       []RoomData       `json:"rooms"`
    51		Connections []ConnectionData `json:"connections,omitempty"`
    52	}
    53	
    54	// RoomData mirrors RoomInput exactly to persist construction inputs.
    55	// Grid is persisted as spatial's own GridType string ("hex" or
    56	// "gridless" — tools/spatial's GridTypeHex/GridTypeGridless), not the
    57	// GridShape iota: the iota is an in-process enumeration order, not a
    58	// wire contract, and would silently reinterpret old blobs if spatial
    59	// ever reordered it. Grid omits when empty (the square zero value) so
    60	// pre-v0.2 blobs and square-only encounters keep byte-identical output.
    61	type RoomData struct {
    62		ID         string         `json:"id"`
    63		Width      int            `json:"width"`
    64		Height     int            `json:"height"`
    65		Grid       string         `json:"grid,omitempty"`
    66		Occluders  []PositionData `json:"occluders,omitempty"`
    67		Boundaries []BoundaryData `json:"boundaries,omitempty"`
    68	}
    69	
    70	// PositionData is the persistent representation of spatial.Position.
    71	type PositionData struct {
    72		X float64 `json:"x"`
    73		Y float64 `json:"y"`
    74	}
    75	
    76	// BoundaryData is the persistent representation of spatial.Boundary.
    77	type BoundaryData struct {
    78		From              PositionData `json:"from"`
    79		To                PositionData `json:"to"`
    80		BlocksMovement    bool         `json:"blocks_movement,omitempty"`
    81		BlocksLineOfSight bool         `json:"blocks_line_of_sight,omitempty"`
    82	}
    83	
    84	// ConnectionData is the persistent representation of a connection.
