   289	// LoadEncounter reconstructs an Encounter from persistent data and re-attached deciders.
   290	// Validation order (R5 — validate all before constructing): nil-equivalent empty Data,
   291	// no rooms, no endings, empty/reserved ending keys (and kind/reached_position checks),
   292	// undeclared outcome ending, room defects (empty/duplicate ID, unrecognized grid shape),
   293	// connection defects (empty/duplicate ID, missing room, self-connection, endpoint out of
   294	// bounds or on an occluder), duplicate member IDs, member's room not in field, member
   295	// position out of bounds, outcome member room/bounds checks, everMembers missing a
   296	// current member.
   297	// Leaf loaders (clock, intel, record) are called and their rejections are wrapped.
   298	// On success, the field is rebuilt via the same path Setup uses (no re-surveil),
   299	// and members are re-placed at persisted positions.
   300	func LoadEncounter(data EncounterData, deciders map[MemberID]Decider) (*Encounter, error) {
   301		// R5: Validate everything before constructing
   302		// No rooms
   303		if len(data.Field.Rooms) == 0 {
   304			return nil, fmt.Errorf("load encounter: no rooms: %w: %w", ErrInvalidData, ErrNoField)
   305		}
   306	
   307		// No endings
   308		if len(data.Endings) == 0 {
   309			return nil, fmt.Errorf("load encounter: bad endings: %w: %w", ErrInvalidData, ErrNoEnding)
   310		}
   311	
   312		// Validate ending keys and kinds
   313		for _, ed := range data.Endings {
   314			if ed.Key == "" || ed.Key == "abandoned" {
   315				return nil, fmt.Errorf("load encounter: bad endings: %w: %w", ErrInvalidData, ErrNoEnding)
   316			}
   317	
   318			if ed.Kind != "reached_position" && ed.Kind != "external" {
   319				return nil, fmt.Errorf("load encounter: unknown ending kind %q: %w", ed.Kind, ErrInvalidData)
   320			}
   321	
   322			// A reached_position ending without a position would panic at
   323			// construction — LoadEncounter is the trust boundary for
   324			// persisted bytes and must reject, never crash (T6 review M2).
   325			if ed.Kind == "reached_position" && (ed.Position == nil || ed.Room == "") {
   326				return nil, fmt.Errorf("load encounter: ending %q reached_position without room/position: %w", ed.Key, ErrInvalidData)
   327			}
   328		}
   329	
   330		// Validate outcome (if present) references a declared ending
   331		if data.Outcome != nil {
   332			found := false
   333			if data.Outcome.Ending == "abandoned" {
   334				found = true // Reserved ending is valid
   335			} else {
   336				for _, ed := range data.Endings {
   337					if ed.Key == data.Outcome.Ending {
   338						found = true
   339						break
   340					}
   341				}
   342			}
   343			if !found {
   344				return nil, fmt.Errorf("load encounter: outcome ending %q not declared: %w", data.Outcome.Ending, ErrInvalidData)
   345			}
   346		}
   347	
   348		// Validate rooms: unique non-empty IDs, recognized grid shape (deferred
   349		// from Opus T1 review — empty/duplicate room IDs previously went
   350		// unvalidated, and connections resolved via last-wins map insertion).
   351		// Reuses ErrNoField: a malformed room list is as unusable as an empty
   352		// one. roomGrids holds each room's constructed Grid so downstream bounds
   353		// checks (connections, members, outcome members) ask the SAME grid the
   354		// room will actually be built with — a hardcoded rectangle check would
   355		// silently diverge from GridlessRoom's inclusive upper bound
   356		// (tools/spatial/gridless.go: IsValidPosition uses x <= Width, not
   357		// x < Width like Square/Hex).
   358		roomMap := make(map[string]bool)
   359		roomsByID := make(map[string]RoomData)
   360		roomGrids := make(map[string]spatial.Grid, len(data.Field.Rooms))
   361		for _, r := range data.Field.Rooms {
   362			if r.ID == "" {
   363				return nil, fmt.Errorf("load encounter: room has empty id: %w: %w", ErrInvalidData, ErrNoField)
   364			}
   365			if roomMap[r.ID] {
   366				return nil, fmt.Errorf("load encounter: duplicate room %q: %w: %w", r.ID, ErrInvalidData, ErrNoField)
   367			}
   368			shape, ok := gridDataToShape(r.Grid)
   369			if !ok {
   370				return nil, fmt.Errorf("load encounter: room %q has unknown grid shape %q: %w: %w", r.ID, r.Grid, ErrInvalidData, ErrNoField)
   371			}
