   577			if err != nil {
   578				return nil, fmt.Errorf("load encounter add connection: %w: %w", ErrInvalidData, err)
   579			}
   580		}
   581	
   582		// Load leaf state (constructors always succeed after validation)
   583		e.clock = loadedClock
   584		e.intelLog = loadedIntel
   585		e.story = loadedLog
   586	
   587		// Re-place members at persisted positions (no surveil here — outcomes already in intel)
   588		for _, m := range data.Members {
   589			entity := &memberEntity{
   590				id:   string(m.ID),
   591				kind: m.Kind,
   592			}
   593	
   594			_, err = e.orchestrator.PlaceEntity(&spatial.PlaceEntityInput{
   595				RoomID:   spatial.RoomID(m.Room),
   596				Entity:   entity,
   597				Position: spatial.Position{X: m.Position.X, Y: m.Position.Y},
   598			})
   599			if err != nil {
   600				return nil, fmt.Errorf("load encounter member placement: %w: %w: %w", ErrInvalidData, ErrBadPlacement, err)
   601			}
   602	
   603			member := &Member{
   604				ID:   m.ID,
   605				Kind: m.Kind,
   606				Room: m.Room,
   607			}
   608			e.members[m.ID] = member
   609			e.everMembers[m.ID] = true
   610	
   611			// Re-attach decider if present — players cannot carry deciders
   612			// (C2, enforced at all three seams: Setup, Join, and load).
   613			if d, ok := deciders[m.ID]; ok {
   614				if m.Kind == KindPlayer {
   615					return nil, fmt.Errorf("load encounter: player %s cannot carry a decider: %w: %w", m.ID, ErrInvalidData, ErrNoMember)
   616				}
   617				e.deciders[m.ID] = d
   618			}
   619		}
   620	
   621		// Restore the full ever-members set (exited members keep Story access)
   622		for _, em := range data.EverMembers {
   623			e.everMembers[em] = true
   624		}
   625	
   626		// Restore declared endings
   627		for _, ed := range data.Endings {
   628			var trigger Trigger
   629			switch ed.Kind {
   630			case "reached_position":
   631				trigger = TriggerReachedPosition{
   632					Room:     ed.Room,
   633					Position: spatial.Position{X: ed.Position.X, Y: ed.Position.Y},
   634					Member:   ed.Member,
   635				}
   636			case "external":
   637				trigger = TriggerExternal{}
   638			}
   639			e.endings = append(e.endings, declaredEnding{key: ed.Key, trigger: trigger})
   640		}
   641	
   642		// Restore outcome if present
   643		if data.Outcome != nil {
   644			outcome := &Outcome{
   645				Ending:  data.Outcome.Ending,
   646				At:      data.Outcome.At,
   647				Members: make([]MemberOutcome, len(data.Outcome.Members)),
   648			}
   649			for i, m := range data.Outcome.Members {
   650				outcome.Members[i] = MemberOutcome{
   651					ID:       m.ID,
   652					Room:     m.Room,
   653					Position: spatial.Position{X: m.Position.X, Y: m.Position.Y},
   654				}
   655			}
   656			e.outcome = outcome
   657		}
   658	
   659		// Store field and connections inputs for future ToData calls. Connections
   660		// are kept sorted by ID (C8 determinism — order is observable in ToData).
   661		e.fieldInput = convertRoomDataToRoomInput(data.Field.Rooms)
   662		e.connectionsInput = convertConnectionDataToConnectionInput(data.Field.Connections)
   663		sort.Slice(e.connectionsInput, func(i, j int) bool { return e.connectionsInput[i].ID < e.connectionsInput[j].ID })
   664	
   665		return e, nil
   666	}
   667	
   668	// convertRoomDataToRoomInput converts RoomData back to RoomInput for storage.
   669	func convertRoomDataToRoomInput(rooms []RoomData) []RoomInput {
   670		result := make([]RoomInput, len(rooms))
   671		for i, rd := range rooms {
   672			// gridDataToShape's ok is ignored: LoadEncounter has already
   673			// validated every room's Grid string before this conversion runs.
   674			shape, _ := gridDataToShape(rd.Grid)
   675			ri := RoomInput{
   676				ID:         rd.ID,
   677				Width:      rd.Width,
   678				Height:     rd.Height,
   679				Grid:       shape,
   680				Occluders:  make([]spatial.Position, len(rd.Occluders)),
   681				Boundaries: make([]spatial.Boundary, len(rd.Boundaries)),
   682			}
   683	
   684			for j, pd := range rd.Occluders {
   685				ri.Occluders[j] = spatial.Position{X: pd.X, Y: pd.Y}
   686			}
   687	
   688			for j, bd := range rd.Boundaries {
   689				ri.Boundaries[j] = spatial.Boundary{
   690					From:              spatial.Position{X: bd.From.X, Y: bd.From.Y},
   691					To:                spatial.Position{X: bd.To.X, Y: bd.To.Y},
   692					BlocksMovement:    bd.BlocksMovement,
   693					BlocksLineOfSight: bd.BlocksLineOfSight,
   694				}
   695			}
   696	
   697			result[i] = ri
   698		}
   699		return result
   700	}
   701	
   702	// convertConnectionDataToConnectionInput converts ConnectionData back to ConnectionInput for storage.
   703	func convertConnectionDataToConnectionInput(conns []ConnectionData) []ConnectionInput {
   704		result := make([]ConnectionInput, len(conns))
   705		for i, cd := range conns {
   706			result[i] = ConnectionInput{
   707				ID:           cd.ID,
   708				From:         cd.From,
   709				To:           cd.To,
   710				FromPosition: spatial.Position{X: cd.FromPosition.X, Y: cd.FromPosition.Y},
   711				ToPosition:   spatial.Position{X: cd.ToPosition.X, Y: cd.ToPosition.Y},
   712			}
   713		}
   714		return result
   715	}

