   289	// LoadEncounter reconstructs an Encounter from persistent data and re-attached deciders.
   290	// Validation order (R5 — validate all before constructing): nil-equivalent empty Data,
   291	// no rooms, no endings, empty/reserved ending keys (and kind/reached_position checks),
   292	// undeclared outcome ending, room defects (empty/duplicate ID, unrecognized grid shape),
   293	// connection defects (empty/duplicate ID, missing room, self-connection, endpoint out of
   294	// bounds or on an occluder), duplicate member IDs, member's room not in field, member
   295	// position out of bounds, outcome member room/bounds checks, everMembers missing a
   296	// current member.
   297	// Leaf loaders (clock, intel, record) are called and their rejections are wrapped.
   298	// On success, the field is rebuilt via the same path Setup uses (no re-surveil),
   299	// and members are re-placed at persisted positions.
   300	func LoadEncounter(data EncounterData, deciders map[MemberID]Decider) (*Encounter, error) {
   301		// R5: Validate everything before constructing
   302		// No rooms
   303		if len(data.Field.Rooms) == 0 {
   304			return nil, fmt.Errorf("load encounter: no rooms: %w: %w", ErrInvalidData, ErrNoField)
   305		}
   306	
   307		// No endings
   308		if len(data.Endings) == 0 {
   309			return nil, fmt.Errorf("load encounter: bad endings: %w: %w", ErrInvalidData, ErrNoEnding)
   310		}
   311	
   312		// Validate ending keys and kinds
   313		for _, ed := range data.Endings {
   314			if ed.Key == "" || ed.Key == "abandoned" {
   315				return nil, fmt.Errorf("load encounter: bad endings: %w: %w", ErrInvalidData, ErrNoEnding)
   316			}
   317	
   318			if ed.Kind != "reached_position" && ed.Kind != "external" {
   319				return nil, fmt.Errorf("load encounter: unknown ending kind %q: %w", ed.Kind, ErrInvalidData)
   320			}
   321	
   322			// A reached_position ending without a position would panic at
   323			// construction — LoadEncounter is the trust boundary for
   324			// persisted bytes and must reject, never crash (T6 review M2).
   325			if ed.Kind == "reached_position" && (ed.Position == nil || ed.Room == "") {
   326				return nil, fmt.Errorf("load encounter: ending %q reached_position without room/position: %w", ed.Key, ErrInvalidData)
   327			}
   328		}
   329	
   330		// Validate outcome (if present) references a declared ending
   331		if data.Outcome != nil {
   332			found := false
   333			if data.Outcome.Ending == "abandoned" {
   334				found = true // Reserved ending is valid
   335			} else {
   336				for _, ed := range data.Endings {
   337					if ed.Key == data.Outcome.Ending {
   338						found = true
   339						break
   340					}
   341				}
   342			}
   343			if !found {
   344				return nil, fmt.Errorf("load encounter: outcome ending %q not declared: %w", data.Outcome.Ending, ErrInvalidData)
   345			}
   346		}
   347	
   348		// Validate rooms: unique non-empty IDs, recognized grid shape (deferred
   349		// from Opus T1 review — empty/duplicate room IDs previously went
   350		// unvalidated, and connections resolved via last-wins map insertion).
   351		// Reuses ErrNoField: a malformed room list is as unusable as an empty
   352		// one. roomGrids holds each room's constructed Grid so downstream bounds
   353		// checks (connections, members, outcome members) ask the SAME grid the
   354		// room will actually be built with — a hardcoded rectangle check would
   355		// silently diverge from GridlessRoom's inclusive upper bound
   356		// (tools/spatial/gridless.go: IsValidPosition uses x <= Width, not
   357		// x < Width like Square/Hex).
   358		roomMap := make(map[string]bool)
   359		roomsByID := make(map[string]RoomData)
   360		roomGrids := make(map[string]spatial.Grid, len(data.Field.Rooms))
   361		for _, r := range data.Field.Rooms {
   362			if r.ID == "" {
   363				return nil, fmt.Errorf("load encounter: room has empty id: %w: %w", ErrInvalidData, ErrNoField)
   364			}
   365			if roomMap[r.ID] {
   366				return nil, fmt.Errorf("load encounter: duplicate room %q: %w: %w", r.ID, ErrInvalidData, ErrNoField)
   367			}
   368			shape, ok := gridDataToShape(r.Grid)
   369			if !ok {
   370				return nil, fmt.Errorf("load encounter: room %q has unknown grid shape %q: %w: %w", r.ID, r.Grid, ErrInvalidData, ErrNoField)
   371			}
   372			roomMap[r.ID] = true
   373			roomsByID[r.ID] = r
   374			roomGrids[r.ID] = buildRoomGrid(shape, r.Width, r.Height)
   375		}
   376	
   377		// Validate connections: unique non-empty IDs, endpoints resolve to
   378		// distinct declared rooms, and endpoints lie within their room's
   379		// bounds (per the room's own grid) and off any occluder.
   380		// ErrBadConnection rides alongside ErrInvalidData so connection defects
   381		// are discriminable from other load rejections.
   382		seenConnectionIDs := make(map[string]bool, len(data.Field.Connections))
   383		for _, c := range data.Field.Connections {
   384			if c.ID == "" {
   385				return nil, fmt.Errorf("load encounter: connection has empty id: %w: %w", ErrInvalidData, ErrBadConnection)
   386			}
   387			if seenConnectionIDs[c.ID] {
   388				return nil, fmt.Errorf("load encounter: duplicate connection %q: %w: %w", c.ID, ErrInvalidData, ErrBadConnection)
   389			}
   390			seenConnectionIDs[c.ID] = true
   391	
   392			fromRoom, ok := roomsByID[c.From]
   393			if !ok {
   394				return nil, fmt.Errorf("load encounter: connection %q references missing room %q: %w: %w", c.ID, c.From, ErrInvalidData, ErrBadConnection)
   395			}
   396			toRoom, ok := roomsByID[c.To]
   397			if !ok {
   398				return nil, fmt.Errorf("load encounter: connection %q references missing room %q: %w: %w", c.ID, c.To, ErrInvalidData, ErrBadConnection)
   399			}
   400			if c.From == c.To {
   401				return nil, fmt.Errorf("load encounter: connection %q connects room %q to itself: %w: %w", c.ID, c.From, ErrInvalidData, ErrBadConnection)
   402			}
   403	
   404			// Both endpoints are required — ToData always populates them, so
   405			// a nil pointer here means the field was absent from the blob
   406			// (not merely zero-valued). Without this check a missing endpoint
   407			// would unmarshal to a nil *PositionData and panic below; worse,
   408			// if the field type were still a value struct, it would silently
   409			// default to (0,0), a legal cell that invents topology.
   410			if c.FromPosition == nil {
   411				return nil, fmt.Errorf("load encounter: connection %q missing from_position: %w: %w", c.ID, ErrInvalidData, ErrBadConnection)
   412			}
   413			if c.ToPosition == nil {
   414				return nil, fmt.Errorf("load encounter: connection %q missing to_position: %w: %w", c.ID, ErrInvalidData, ErrBadConnection)
   415			}
   416	
   417			if !roomGrids[c.From].IsValidPosition(spatial.Position{X: c.FromPosition.X, Y: c.FromPosition.Y}) {
   418				return nil, fmt.Errorf("load encounter: connection %q from-position out of bounds: %w: %w", c.ID, ErrInvalidData, ErrBadConnection)
   419			}
   420			if !roomGrids[c.To].IsValidPosition(spatial.Position{X: c.ToPosition.X, Y: c.ToPosition.Y}) {
   421				return nil, fmt.Errorf("load encounter: connection %q to-position out of bounds: %w: %w", c.ID, ErrInvalidData, ErrBadConnection)
   422			}
   423	
   424			for _, occ := range fromRoom.Occluders {
   425				if occ.X == c.FromPosition.X && occ.Y == c.FromPosition.Y {
   426					return nil, fmt.Errorf("load encounter: connection %q from-position on occluder: %w: %w", c.ID, ErrInvalidData, ErrBadConnection)
   427				}
   428			}
   429			for _, occ := range toRoom.Occluders {
   430				if occ.X == c.ToPosition.X && occ.Y == c.ToPosition.Y {
   431					return nil, fmt.Errorf("load encounter: connection %q to-position on occluder: %w: %w", c.ID, ErrInvalidData, ErrBadConnection)
   432				}
   433			}
   434		}
   435	
   436		// Validate members: no duplicates, rooms exist, positions in bounds
   437		seenIDs := make(map[MemberID]bool)
   438		for _, m := range data.Members {
   439			// Empty member IDs are unreachable (Setup and Join both reject).
   440			if m.ID == "" {
   441				return nil, fmt.Errorf("load encounter: empty member id: %w", ErrInvalidData)
   442			}
   443			if seenIDs[m.ID] {
   444				return nil, fmt.Errorf("load encounter: duplicate member %q: %w", m.ID, ErrInvalidData)
   445			}
   446			seenIDs[m.ID] = true
   447	
   448			if !roomMap[m.Room] {
   449				return nil, fmt.Errorf("load encounter: member %q room %q not in field: %w", m.ID, m.Room, ErrInvalidData)
   450			}
   451	
   452			// Validate position in bounds — grid-deferred: the room's own
   453			// constructed Grid decides validity (see roomGrids above).
   454			if !roomGrids[m.Room].IsValidPosition(spatial.Position{X: m.Position.X, Y: m.Position.Y}) {
   455				return nil, fmt.Errorf("load encounter: member %q position out of bounds: %w", m.ID, ErrInvalidData)
