   501		if err != nil {
   502			return nil, fmt.Errorf("load encounter intel: %w: %w", ErrInvalidData, err)
   503		}
   504	
   505		loadedLog, err := record.LoadLog(data.Log)
   506		if err != nil {
   507			return nil, fmt.Errorf("load encounter log: %w: %w", ErrInvalidData, err)
   508		}
   509	
   510		// All validated; now reconstruct via the same path Setup uses
   511		e := &Encounter{
   512			members:     make(map[MemberID]*Member),
   513			everMembers: make(map[MemberID]bool),
   514			deciders:    make(map[MemberID]Decider),
   515			endings:     nil,
   516		}
