   518		// Rebuild field via setup path (no bus, no surveil)
   519		e.orchestrator = spatial.NewBasicRoomOrchestrator(spatial.BasicRoomOrchestratorConfig{
   520			ID:     "encounter-orchestrator",
   521			Type:   "orchestrator",
   522			Layout: spatial.LayoutTypeOrganic,
   523		})
