   525		// Create all rooms, reusing each room's already-constructed Grid
   526		// (roomGrids, built above) so validation and placement agree exactly.
   527		spatialRoomMap := make(map[string]*spatial.BasicRoom)
   528		for _, ri := range data.Field.Rooms {
   529			room := spatial.NewBasicRoom(spatial.BasicRoomConfig{
   530				ID:   ri.ID,
   531				Type: "room",
   532				Grid: roomGrids[ri.ID],
   533			})
