   543				_, err = e.orchestrator.PlaceEntity(&spatial.PlaceEntityInput{
   544					RoomID:   spatial.RoomID(ri.ID),
   545					Entity:   occluder,
   546					Position: spatial.Position{X: pos.X, Y: pos.Y},
   547				})
   548				if err != nil {
   549					return nil, fmt.Errorf("load encounter occluder placement: %w: %w: %w", ErrInvalidData, ErrBadPlacement, err)
   550				}
   551			}
   552	
   553			// Add boundaries
   554			for _, b := range ri.Boundaries {
   555				boundary := spatial.Boundary{
   556					From:              spatial.Position{X: b.From.X, Y: b.From.Y},
   557					To:                spatial.Position{X: b.To.X, Y: b.To.Y},
   558					BlocksMovement:    b.BlocksMovement,
   559					BlocksLineOfSight: b.BlocksLineOfSight,
   560				}
