   594			_, err = e.orchestrator.PlaceEntity(&spatial.PlaceEntityInput{
   595				RoomID:   spatial.RoomID(m.Room),
   596				Entity:   entity,
   597				Position: spatial.Position{X: m.Position.X, Y: m.Position.Y},
   598			})
   599			if err != nil {
   600				return nil, fmt.Errorf("load encounter member placement: %w: %w: %w", ErrInvalidData, ErrBadPlacement, err)
   601			}
