   400		positions := make([]Position, 0)
   401		for dq := -iRadius; dq <= iRadius; dq++ {
   402			rMin := intMax(-iRadius, -dq-iRadius)
   403			rMax := intMin(iRadius, -dq+iRadius)
   404			for dr := rMin; dr <= rMax; dr++ {
