package encounter

import (
	"strings"
	"testing"

	"github.com/KirkDiggler/rpg-toolkit/tools/spatial"
	"github.com/stretchr/testify/require"
)

func TestReviewerProbeIntelDeltaSubjectOrderIsObservable(t *testing.T) {
	orders := map[string]struct{}{}
	for n := 0; n < 128; n++ {
		enc, err := NewEncounter(&SetupInput{
			Field: FieldInput{Rooms: []RoomInput{{ID: "room", Width: 4, Height: 4}}},
			Members: []MemberInput{
				{ID: "a", Kind: KindPlayer, Room: "room", Position: spatial.Position{X: 0, Y: 0}},
				{ID: "b", Kind: KindPlayer, Room: "room", Position: spatial.Position{X: 1, Y: 0}},
				{ID: "c", Kind: KindPlayer, Room: "room", Position: spatial.Position{X: 2, Y: 0}},
			},
			Endings: []EndingInput{{Key: "stop", Trigger: TriggerExternal{}}},
		})
		require.NoError(t, err)
		out, err := enc.Move(&MoveInput{Member: "a", To: spatial.Position{X: 0, Y: 1}})
		require.NoError(t, err)
		got := out.IntelDeltas["a"].Refreshed
		orders[string(got[0])+","+string(got[1])] = struct{}{}
	}
	require.Greater(t, len(orders), 1)
	keys := make([]string, 0, len(orders))
	for key := range orders {
		keys = append(keys, key)
	}
	t.Logf("observed public SurveilOutput.Refreshed orders: %s", strings.Join(keys, " / "))
}

